/**
 * @distilled.cloud/tinybird -- Tinybird SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * that `scripts/convert.ts` reads out of Tinybird's API reference, mirrored
 * as Markdown under `specs/spec-mirror-tinybird/specs/api-reference`.
 * Everything else in this folder is hand-written.
 *
 * One module per reference page: `datasource`, `events`, `query`, `pipe`,
 * `api_endpoints`, `copy_pipes`, `materialized_views`, `sink_pipes`, `token`,
 * `environment_variables`, `jobs`, `analyze` and `organizations`. Import each
 * from its subpath.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Tinybird from "@distilled.cloud/tinybird";
 * import * as Events from "@distilled.cloud/tinybird/events";
 * import * as Query from "@distilled.cloud/tinybird/query";
 *
 * const program = Effect.gen(function* () {
 *   const ingested = yield* Events.sendEvents({
 *     name: "events",
 *     wait: true,
 *     body: '{"timestamp":"2026-11-17 00:00:00","city":"Chicago","amount":3}\n',
 *   });
 *   const bytes = yield* Query.querySql({
 *     q: "SELECT city, sum(amount) AS total FROM events GROUP BY city FORMAT JSON",
 *   });
 *   const { data } = JSON.parse(new TextDecoder().decode(bytes));
 *   return { ingested, data };
 * });
 *
 * const Live = Layer.mergeAll(
 *   FetchHttpClient.layer,
 *   Tinybird.CredentialsFromEnv,
 * );
 *
 * program.pipe(Effect.provide(Live), Effect.runPromise).then(console.log);
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { TinybirdProtocol, type TinybirdOpError, type TinybirdOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
